 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries a JOIN tradeskill_recipe r ON r.id=a.recipe_id WHERE a.item_id=58236 AND a.componentcount=1 AND a.iscontainer=0 AND r.id<>10227 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0)=2 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=58235)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=58236)=1 AND EXISTS(SELECT 1 FROM tradeskill_recipe_entries k WHERE k.recipe_id=r.id AND k.iscontainer=1 AND k.item_id IN(17276,10)))THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC144 new effective-kit conflict';END IF;
